    add("interference", t_interference, (("a",), {}), (("b",), {}), (("--move",), mv), loc)
    add("thickness", t_thickness)
    add("bbox", t_bbox)
    add("sweep", t_sweep)
    add("probe", t_probe)
    add("submit", t_submit)
